// Üretilen dosya: tool/ozgun/uret.py. Mühendislik ve Tasarım · Proje yönetimi, kalite ve güvenlik mühendisliği (zor).
const ozEngineering13Zor = <(String, String, List<String>, String)>[
  ('Serbest bolluk (free float) ile toplam bolluk (total float) arasındaki fark nedir?', 'Serbest bolluk yalnızca bir sonraki etkinliğin en erken başlamasını bozmayan gecikme payıdır', ['Serbest bolluk, her zaman toplam bollukten daha büyük bir değerdir', 'Serbest bolluk yalnızca kritik yoldaki etkinliklerde vardır', 'İkisi arasında hiçbir fark yoktur'], 'Serbest bolluk ardıl etkinliğin erken başlangıcını etkilemeden kullanılabilecek paydır; toplam bolluk ise proje bitişini bozmayan paydır. Serbest bolluk toplam bollukten büyük olamaz.'),
  ('Bir ağda ES = 4, süre = 3, ardıl etkinliklerin en geç başlamalarının en küçüğü 15\'tir. Etkinliğin toplam bolluğu kaç gündür?', '8', ['4', '11', '12'], 'Etkinliğin EF değeri 4 + 3 = 7\'dir. LF = 15 olduğundan LS = 12 ve toplam bolluk = LS − ES = 12 − 4 = 8 gündür.'),
  ('Bir planda \'gecikme (lag)\' eklemek yerine \'öne alma (lead)\' kullanmak ne sonuç verir?', 'Ardıl etkinlik öncül bitmeden bir miktar önce başlayabilir', ['Ardıl etkinlik öncül bittikten sonra bekler', 'İki etkinlik birleştirilir', 'Ardıl etkinliğin süresi, öncülün süresinin iki katına çıkar'], 'Lead, ardıl etkinliğin öncül tamamlanmadan örtüşerek başlamasına izin verir; lag ise bekleme ekler. Beton kürlenmesi için eklenen bekleme tipik bir lag\'dir.'),
  ('Bir yolda üç etkinliğin varyansları 1, 4 ve 4 gün² ise yolun standart sapması kaç gündür?', '3', ['9', '2', '1,5'], 'Bağımsız etkinliklerde varyanslar toplanır: 1 + 4 + 4 = 9 gün². Standart sapma karekök 9 = 3 gündür.'),
  ('Kritik yolun beklenen süresi 40 gün, standart sapması 5 gündür. Normal dağılım varsayımıyla projenin 45 gün içinde bitme olasılığı yaklaşık kaçtır?', 'Yaklaşık %84', ['Yaklaşık %50', 'Yaklaşık %68', 'Yaklaşık %97'], 'Z = (45 − 40)/5 = 1\'dir. Standart normal dağılımda Z = 1 için birikimli olasılık yaklaşık 0,84\'tür.'),
  ('Bir köprü projesinin WBS\'si yalnızca \'çelik\', \'beton\', \'işçilik\' maliyet başlıklarıyla kurulmuş. Bu yapının başlıca sakıncası nedir?', 'Çıktılara değil girdilere odaklandığından kapsam ve ilerleme izlenemez', ['Maliyet tahmini imkânsız hâle gelir', 'Proje takvimi kaçınılmaz olarak uzar ve maliyet de artar', 'Paydaşlar sözleşmeyi bozar'], 'İyi bir WBS teslim edilecek çıktılara göre kurulur. Girdi kategorileri iş kapsamını ve ilerlemeyi göstermez.'),
  ('Bir projede kaynak harcaması ve ekip büyüklüğü zaman içinde tipik olarak hangi biçimde değişir?', 'Başta düşük, yürütmede en yüksek, kapanışa doğru azalan', ['Hep sabit kalır', 'Başta en yüksek, sonra düzenli olarak artarak sürekli yükselen', 'Yalnızca kapanışta artar'], 'Proje yaşam döngüsünde maliyet ve personel yoğunluğu yürütme aşamasında tepe yapar, kapanışta düşer. Değişiklik maliyeti ise zamanla artar.'),
  ('Bir müşteri, proje bitiş tarihi ve bütçe sabitken ek özellikler istiyor. Proje yöneticisi ne yapmalıdır?', 'Değişikliği resmî süreçle değerlendirip süre, maliyet etkisini müşteriye bildirmelidir', ['İstekleri sessizce kabul edip ekibi fazla mesaiye zorlamalıdır', 'Müşteriyi reddedip projeyi iptal etmelidir', 'Kaliteyi düşürerek eklemeleri sığdırmalıdır'], 'Kapsam artışı, onaylanmadan eklendiğinde \'kapsam kayması\' olur. Değişiklik talebi etkisi analiz edilerek resmî olarak karara bağlanmalıdır.'),
  ('Ekip müşteri istemediği hâlde ürüne \'bonus\' özellikler ekliyor. Proje yönetimi açısından bu davranışın adı ve sorunu nedir?', 'Gold plating; gereksiz iş ve risk yaratır', ['Kapsam doğrulama; çıktı kabul edilir ve kaliteyi artırır', 'Hızlı izleme; süreyi kısaltır', 'Kaynak dengeleme; maliyeti azaltır'], 'Gold plating, gereksinim dışı ek özellik eklemektir. Ek test, süre ve risk getirir, kapsamın kontrolünü bozar.'),
  ('Bir kritik etkinlik normalde 10 gün ve 5000 TL, acil durumda 8 gün ve 6200 TL\'dir. Etkinliği 1 gün kısaltmanın maliyeti kaç TL\'dir?', '600', ['1200', '2400', '300'], 'Süre kısaltma maliyet eğimi = (6200 − 5000)/(10 − 8) = 600 TL/gündür. Kısaltma maliyeti gün başına budur.'),
  ('Kritik yolu kısaltırken ağda neden sürekli en düşük maliyet eğimli kritik etkinlik seçilir ve takip eden adımlarda ağ yeniden hesaplanır?', 'Kısaltma sonrası başka bir yol da kritik hâle gelebilir', ['Kritik yol, ağ yeniden hesaplanmadan da hiçbir zaman değişmez', 'Maliyet eğimi süreyle ters orantılıdır', 'En ucuz etkinliği seçmek kuraldır, nedeni yoktur'], 'Kritik yol kısalınca, ona yakın uzunluktaki yollar kritik olabilir; bu yüzden her adımda ağ yeniden değerlendirilir.'),
  ('Bütçe tamamlanmada (BAC) 500 bin TL ve CPI 0,8 sabit kalacaksa tamamlanma tahmini (EAC = BAC/CPI) kaç bin TL olur?', '625 bin TL', ['400 bin TL', '500 bin TL', '580 bin TL'], 'EAC = BAC/CPI = 500/0,8 = 625 bin TL\'dir. Mevcut verimlilik sürerse proje bütçeyi 125 bin TL aşar.'),
  ('Beklenmedik (bilinmeyen-bilinmeyen) riskler için yönetim tarafından ayrılan ve proje yöneticisinin tek başına kullanamadığı bütçe payına ne ad verilir?', 'Yönetim rezervi', ['Olasılık rezervi', 'Kritik yol payı', 'Kalite bütçesi'], 'Yönetim rezervi tanımlanmamış risklere karşı tutulur ve kullanımı üst yönetim onayını gerektirir. Bilinen risklerin payı ise olasılık rezervidir.'),
  ('Gereksinimleri başta kesin bilinen ve değişmesi çok maliyetli olan bir uçak aviyonik projesinde hangi yaklaşım daha uygun görülür?', 'Doğrulama adımları belgelenen V modeli', ['Gereksinimleri her hafta değiştiren serbest yaklaşım', 'Hiç belgelendirmeden çalışan prototip döngüsü', 'Yalnızca kullanıcı geri bildirimine dayalı deneme yanılma'], 'Güvenlik açısından kritik, gereksinimleri kararlı ve sertifikasyon gerektiren işlerde izlenebilirliği güçlü V modeli tercih edilir.'),
  ('Boehm\'in 1986\'da önerdiği spiral modelin ayırt edici özelliği nedir?', 'Her turda risk analizi yapan, risk odaklı bir döngü olması', ['Yalnızca bir kez geçilen ve riske hiç bakmayan doğrusal aşamalar içermesi', 'Müşteriyi sürece hiç katmaması', 'Testi en sona bırakması'], 'Spiral model, tasarım-prototip-değerlendirme turlarında riskleri her turda analiz ederek yönlendirilir.'),
  ('Kaynak düzleştirme (smoothing) ile kaynak dengeleme (leveling) arasındaki ayrım nedir?', 'Düzleştirme bolluk sınırları içinde kalır, bitiş tarihini ve kritik yolu değiştirmez', ['Düzleştirme kritik yolu uzatır, dengeleme uzatmaz', 'Düzleştirme kritik yolu uzatır, dengeleme ise bitiş tarihini hiç etkilemez', 'Dengeleme yalnızca maliyeti düzeltir'], 'Smoothing yalnızca bolluk içinde kaydırma yapar; leveling ise kaynak kısıtı nedeniyle bitişi uzatabilir.'),
  ('Brooks Yasası (1975) gecikmiş bir yazılım projesi için ne söyler?', 'Gecikmiş projeye insan eklemek onu daha da geciktirir', ['Gecikmiş projeye insan eklemek süreyi doğru orantılı kısaltır', 'Gecikmiş proje mutlaka iptal edilmelidir', 'Gecikme yalnızca testten kaynaklanır'], 'Yeni kişilerin eğitim ve iletişim yükü, kısa vadede ekibin verimini düşürebilir; bu \'Mythical Man-Month\' kitabındaki tespittir.'),
  ('Sahada bir mühendis sözlü onayla bir tasarım değişikliği yaptırıyor ama kayıt tutulmuyor. Sonuçta en büyük risk nedir?', 'Dokümantasyonun gerçek durumla uyuşmaması ve izlenebilirliğin kaybı', ['Projenin hızla kâr etmesi', 'Ekibin motivasyonunun artması', 'Maliyetin hiçbir koşulda artmaması ve belgelerin kendiliğinden güncellenmesi'], 'Kayıtsız değişiklik, çizim ile sahadaki uygulama arasında fark doğurur ve sonraki bakım ile denetimde hataya yol açar.'),
  ('Bir proje teknik olarak teslim edilmiş ama müşteri kabul imzası hiç alınmamış. Bu durumda ne eksiktir?', 'Resmî kabul ve kapanış, yani teslimin onaylanması', ['Yalnızca ekip için kutlama toplantısı ve teşekkür yazısı', 'Ek bütçe talebi', 'Yeni bir risk analizi'], 'Kapanışta çıktıların müşteri tarafından resmen kabul edilmesi gerekir; yoksa sorumluluk ve ödeme belirsiz kalır.'),
  ('Goldratt\'ın kritik zincir yönteminde (1997) hangi uygulama öne çıkar?', 'Etkinlik tahminlerinden güvenlik paylarını alıp proje sonunda tampon oluşturmak', ['Tüm etkinliklere eşit bolluk dağıtmak', 'Kritik yolu tamamen yok saymak', 'Her etkinliğe ayrı bir bütçe atayıp bolluğu tamamen ortadan kaldırmak'], 'Kritik zincir, etkinliklere gizlenmiş payları kaldırıp proje ve besleme tamponları toplar; öğrenci sendromu ve Parkinson Yasası etkilerini azaltır.'),
  ('Parametrik tahminde 1 m² duvar için 3 adam-saat gerektiği biliniyorsa 400 m² duvar kaç adam-saat sürer?', '1200 adam-saat', ['403 adam-saat', '1600 adam-saat', '1000 adam-saat'], 'Parametrik tahmin birim oranını ölçüyle çarpar: 400 × 3 = 1200 adam-saattir.'),
  ('Bir kontrol grafiğinde kontrol sınırları ile şartname (tolerans) sınırları birbirine karıştırılırsa ne olur?', 'Süreç kontrol altındaysa bile şartnameye uymayabilir; ikisi farklı kavramlardır', ['Hiçbir sorun çıkmaz', 'Süreç otomatik olarak daha iyi olur', 'Tüm ürünler şartnameye uygun sayılır ve hiçbir ayrı kontrol gerekmez'], 'Kontrol sınırları sürecin kendi davranışından, şartname sınırları ise müşteri ihtiyacından gelir; birbirine bağlı değildir.'),
  ('USL = 10,6, LSL = 9,4, süreç ortalaması 10,2, σ = 0,2 ise Cpk kaçtır?', '0,67', ['1,33', '1,00', '0,40'], 'Cpk = min[(USL − μ), (μ − LSL)]/(3σ). Küçük taraf (10,6 − 10,2) = 0,4; 0,4/0,6 = 0,67\'dir.'),
  ('Üç ardışık adımın ilk geçiş verimleri 0,95, 0,90 ve 0,80 ise yuvarlanmış iş hacmi verimi (RTY) yaklaşık kaçtır?', '0,68', ['0,88', '0,95', '0,72'], 'RTY, adım verimlerinin çarpımıdır: 0,95 × 0,90 × 0,80 = 0,684\'tür. Adımlar arttıkça toplam verim düşer.'),
  ('Bir ürünün toplam akış süresi 10 gün olup bunun yalnızca 2 saati fiilen işlenmekle geçiyorsa (1 gün = 24 saat) değer katan sürenin oranı yaklaşık nedir?', 'Yaklaşık %0,8', ['Yaklaşık %8', 'Yaklaşık %20', 'Yaklaşık %50'], 'Toplam süre 240 saattir; 2/240 ≈ 0,0083, yani yaklaşık %0,8. Geri kalan süre bekleme ve taşıma gibi değersiz zamandır.'),
  ('Toyota\'daki \'jidoka\' (otonomasyon) ilkesi ne demektir?', 'Makinenin hata görünce kendiliğinden durup insanı uyarması', ['Her makinenin insansız, tam otomatik ve kusursuz çalışması', 'Üretim hızını makine duruşu olmadan en yüksek düzeye çıkarmak', 'Stokun sıfırlanması'], 'Jidoka, kusuru fark edince hattı durduran insan-zekâlı otomasyondur; kusurlu parça sonraki adıma geçmez.'),
  ('SMED çalışmasında \'dış hazırlık\' ile \'iç hazırlık\' ayrımı neden önemlidir?', 'Dış hazırlık makine çalışırken yapılabildiğinden duruş süresi kısalır', ['Dış hazırlık makineyi yavaşlatır', 'İç hazırlık makine çalışırken yapılır', 'İkisi de makine durmadan yapılamaz'], 'Yalnız makine durmuşken yapılabilen işler iç hazırlıktır; mümkün olanları dışa taşımak duruşu azaltır.'),
  ('Bir atölyede çalışanlar sık kullanılan aletlerin gölge panosunda kendi izlerinin çizildiği yerde asılı durmasını sağlıyor. Bu hangi 5S adımının örneğidir?', 'Seiton (düzenleme)', ['Seiri (ayıklama)', 'Seiso (temizlik)', 'Shitsuke (disiplin)'], 'Aletlerin yerini işaretleyip eksiklerin bir bakışta görülmesi düzenleme adımıdır.'),
  ('Bir vardiya 480 dk planlı çalışmadır, 60 dk plansız duruş olmuştur. Kullanılabilirlik yüzdesi kaçtır?', '%87,5', ['%12,5', '%80', '%93'], 'Kullanılabilirlik = (480 − 60)/480 = 420/480 = 0,875, yani %87,5\'tir.'),
  ('AQL (kabul edilebilir kalite düzeyi) için doğru ifade hangisidir?', 'Örnekleme planında kabul edilebilir sayılan en yüksek hatalı oranı gösterir', ['Her ürünün sıfır hatalı olması gerektiğini ve örneklemin gereksiz olduğunu', 'Müşterinin asla kabul etmeyeceği hatalı oranıdır', 'Kalite maliyetinin yüzdesidir'], 'AQL, tedarikçi sürecinin ortalama olarak kabul edilebilir bulunduğu en yüksek hatalı oranıdır; kabul sayısı bu orana göre planlanır.'),
  ('Taguchi\'nin kayıp fonksiyonu fikri neyi söyler?', 'Ürün özelliği hedef değerden saptıkça, tolerans içinde bile olsa, topluma kayıp artar', ['Tolerans içindeki her ürün aynı kalitededir', 'Kayıp yalnızca tolerans sınırının dışında başlayıp yukarı doğru artar', 'Kayıp, üretici maliyetinden bağımsızdır'], 'Taguchi\'ye göre hedeften her sapma kayıp yaratır ve bu kayıp sapmanın karesiyle orantılıdır; amaç hedef etrafında değişkenliği azaltmaktır.'),
  ('Deneylerde \'rastgele sırayla yapma\' ilkesi hangi sorunu azaltmak için uygulanır?', 'Zamanla değişen gizli etkenlerin (sıcaklık, takım aşınması) sonuçları yanıltması', ['Deney sayısının fazla olması ve faktör sayısının gereksiz artması', 'Maliyetin yüksek olması', 'Faktör sayısının çok olması'], 'Koşulları sıralı yaparsanız zaman etkisi (örneğin aşınma) bir faktörle karışabilir; rastgele sıralama bu karışmayı dağıtır.'),
  ('Gage R&R çalışmasında R&R harfleri neyi ifade eder?', 'Tekrarlanabilirlik ve yeniden üretilebilirlik', ['Rastgelelik ve gerçeklik', 'Risk ve güvenilirlik çalışmasında kullanılan değerler', 'Raporlama ve inceleme'], 'Tekrarlanabilirlik aynı operatör ve aletle, yeniden üretilebilirlik farklı operatörlerle ölçüm değişkenliğini gösterir; ikisi ölçüm sisteminin gürültüsüdür.'),
  ('Parçalar arasındaki gerçek farktan çok ölçüm sistemi varyasyonunun büyük çıktığı bir Gage R&R sonucu neyi gösterir?', 'Ölçüm sistemi bu süreç için yetersizdir ve iyileştirilmelidir', ['Süreç mükemmeldir', 'Ölçüm sistemi örnek niteliğindedir, süreçte hiçbir değişiklik gerekmez', 'Parçalar birbirinin aynısıdır'], 'Ölçüm hatası parça farklarını bastırıyorsa, süreç kararları güvenilmez olur. Önce ölçüm sistemi düzeltilmelidir.'),
  ('10,00 mm\'lik referans blokla yapılan beş ölçüm 10,12; 10,11; 10,13; 10,12; 10,12 mm çıkıyor. Bu alet için hangisi doğrudur?', 'Tekrarlanabilir ama yaklaşık 0,12 mm sapmalı', ['Hem doğru hem hassastır, sapma yoktur', 'Ne doğru ne de tekrarlanabilir, sapması rastgele bir alet', 'Doğru ama tekrarlanamaz'], 'Okumalar birbirine yakın (tekrarlanabilir) ama referanstan yaklaşık 0,12 mm uzaktadır; sistematik hata kalibrasyonla düzeltilir.'),
  ('Bir hat arızasında nedenler şöyle sayılıyor: A 50, B 30, C 12, D 8 adet. Toplamın yaklaşık %80\'ini kaç neden oluşturur (en az sayıda)?', 'İki neden (A ve B)', ['Tek neden (A)', 'Üç neden', 'Dört neden (A, B, C ve D birlikte)'], 'A+B = 80, toplam 100 olduğundan %80\'e iki neden yeter. Pareto ilkesinin tipik \'az sayıda kritik neden\' örneğidir.'),
  ('Pareto analizinin yanıltıcı olabileceği durum hangisidir?', 'Sıklığı düşük hatanın şiddeti çok yüksek olabilir ve gözden kaçar', ['Tüm hataların maliyeti birbirine eşit olduğunda', 'Veriler tarih sırasına konulduğunda', 'Grafik çizilirken renk kullanılırsa'], 'Pareto yalnızca sayıya göre sıralarsa, nadir ama ölümcül hatalar küçük görünür. Bu yüzden şiddete göre ağırlıklandırma düşünülmelidir.'),
  ('Bir makinenin MTBF değeri 90 saat, MTTR değeri 10 saattir. Kullanılabilirliği (availability) yaklaşık kaçtır?', '%90', ['%10', '%80', '%99'], 'Kullanılabilirlik = MTBF/(MTBF + MTTR) = 90/100 = %90\'dır.'),
  ('Arıza oranı λ = 0,002 arıza/saat olan üstel bir bileşenin 500 saat sorunsuz çalışma olasılığı R = e^(−λt) ile yaklaşık kaçtır?', '0,37', ['0,63', '0,90', '0,05'], 'λt = 0,002 × 500 = 1; e⁻¹ ≈ 0,368\'dir. Ortalama ömür (1/λ = 500 saat) kadar çalışma olasılığı yaklaşık %37\'dir.'),
  ('Weibull dağılımının şekil parametresi β < 1 ise arıza oranı zamanla nasıl değişir?', 'Azalır (erken arıza davranışı)', ['Artar (aşınma davranışı)', 'Her zaman sıfıra yaklaşarak azalır ve hiç arıza oluşmaz', 'Önce sabit sonra sıçrar'], 'β < 1 azalan, β = 1 sabit, β > 1 artan arıza oranını gösterir. β < 1 küvet eğrisinin başlangıçtaki bebek ölümü bölgesine karşılık gelir.'),
  ('Kritik bir pompa için tek büyük pompa yerine paralel çalışan iki pompa seçilmesinin güvenilirlik açısından asıl kazancı nedir?', 'Birinin arızasında diğerinin görevi sürdürmesi', ['Pompa veriminin otomatik olarak iki katına çıkması', 'Montajın kolaylaşması', 'Bakım gerektirmemesi'], 'Yedeklilik tek hata noktasını ortadan kaldırır. Ancak ortak neden arızaları (aynı elektrik hattı gibi) kazancı sınırlayabilir.'),
  ('Bir işyeri yüksek gürültüyü azaltmak yerine herkese kulak tıkacı dağıtıyor. Bu yaklaşım neden yetersiz sayılır?', 'KKD hiyerarşide en son basamaktır ve kaynakta çözüm sunmaz', ['Kulak tıkacı hiçbir koruma sağlamaz', 'Gürültünün yasal olarak hiçbir koşulda sorun sayılmaması ve KKD\'nin yeterli olması', 'Tıkaç yalnızca yöneticiler içindir'], 'Önce gürültü kaynağı sessizleştirilmeli ya da yalıtılmalıdır; KKD kullanıcıya bağımlı olduğundan son savunma hattıdır.'),
  ('Bir çalışan KKD olarak tam yüz maskesi takıyor ama maskeyi sakalı nedeniyle yüze tam oturtamıyor. Asıl sorun nedir?', 'Sızdırmazlık sağlanamayacağından koruma büyük ölçüde kaybolur', ['Maske fazla ısınır', 'Çalışan daha az görür ve maske ömrü kısalır', 'Maske ömrü uzar'], 'Solunum cihazlarının koruması yüz ile maske arasındaki sızdırmazlığa bağlıdır; sakal ya da saç bunu bozar, bu nedenle uygunluk (fit) testi yapılır.'),
  ('Bir pres makinesinin ana şalteri kilitlendi, ancak sıkıştırılmış hava hattı basınçlı kalmıştı. Hangi adım eksiktir?', 'Depolanmış (artık) enerjinin boşaltılması ve sıfır enerjinin doğrulanması', ['Yalnızca kilidin rengini ve makine adının etiketine yazılması', 'Makine adının etikete yazılması', 'Çalışanın imzası'], 'Elektrik kesilse bile basınç, yay, kondansatör ya da yerçekimi gibi depolanmış enerji yaralanma yaratabilir; boşaltıp \'sıfır enerji\' doğrulanmalıdır.'),
  ('Bir vardiya amiri, bakım bitmeden önce kilitleri kendi yetkisiyle kaldırıp makineyi çalıştırıyor. Bu davranış neden büyük hata sayılır?', 'İzolasyonu kuran kişinin onayı olmadan açmak içeride çalışanı ölüm tehlikesine sokar', ['Yalnızca elektrik faturasını artırır ve makineye zarar verir', 'Makine hemen bozulur', 'Etiketler karışır'], 'Kilit yalnızca takan kişi (yetkili çalışan) tarafından, işin bittiği doğrulandıktan sonra açılmalıdır; aksi durumda içerideki çalışan ezilme ya da elektrik çarpması riskine girer.'),
  ('James Reason\'ın \'İsviçre peyniri modeli\' kazaları nasıl açıklar?', 'Birden çok savunma katmanındaki deliklerin aynı anda hizalanmasıyla', ['Yalnızca tek bir işçinin dikkatsizliğiyle ve sistem hatası olmaksızın', 'Doğa olaylarıyla yalnızca', 'Kötü niyetli sabotajla yalnızca'], 'Model, her savunma katmanının zayıf noktaları (delikler) olduğunu, tehlikeli olayın bu deliklerin sıralanmasıyla zarara dönüştüğünü anlatır.'),
  ('Risk matrislerinin bilinen bir sınırlaması hangisidir?', 'Çok düşük olasılıklı ama felaket şiddetli olaylarla sık ama hafif olayları aynı puana getirebilir', ['Hesap yapmaya hiç yer bırakmaz ve her risk için tek bir kesin değer verir', 'Yalnızca makineler için çalışması', 'Her zaman fazla ayrıntılı olması'], 'Matris, farklı türden risklerin benzer puanlarda görünmesine yol açabilir; olasılık ve şiddet kategorileri kaba olduğundan yargılar kişiye göre değişebilir.'),
  ('Acil durdurma düğmelerinin çoğunlukla normalde kapalı (NC) kontakla bağlanmasının nedeni nedir?', 'Kablo kopması ya da kontak arızasında devre açılıp makinenin durması', ['Daha ucuz olması ve daha az kablo gerektirmesi', 'Daha az enerji harcaması', 'Daha hızlı çalışması'], 'Kablo kopması \'durdur\' komutuyla aynı sonucu verir; böylece arıza emniyetli yöne düşer (fail-safe).'),
  ('Türkiye\'deki mevzuata göre risk değerlendirmesi, az tehlikeli sınıftaki işyerlerinde en geç kaç yılda bir yenilenir?', 'Altı', ['İki', 'Dört', 'On iki'], 'Risk değerlendirmesi çok tehlikeli işyerlerinde iki, tehlikeli işyerlerinde dört, az tehlikeli işyerlerinde altı yılda bir yenilenir; yeni tehlike ya da kaza durumunda ayrıca güncellenir.'),
  ('Türkiye\'de İSG kurulu kurma zorunluluğu hangi ölçütle doğar?', 'Elli ve üzeri çalışanı olan, altı aydan uzun süren işyerlerinde', ['Yalnızca on kişiden az çalışanı olan ve kısa süreli işyerlerinde', 'Sadece kamu kurumlarında', 'Yalnızca çok tehlikeli işlerde'], 'Kural olarak elli ve daha fazla çalışanı bulunan ve altı aydan uzun süren işlerin yapıldığı işyerlerinde iş sağlığı ve güvenliği kurulu kurulur.'),
  ('Bilgisayar sunucu odasında kalıntı bırakmayan ve elektriği iletmeyen bir söndürme yöntemi isteniyor. Hangisi daha uygundur?', 'Karbondioksit ya da temiz gaz sistemi', ['Su püskürtmeli yağmurlama ve elle su serpme', 'Köpüklü söndürücü', 'Kum serpmek'], 'CO₂ ve temiz gazlar (örneğin inert gaz) iletken değildir ve kalıntı bırakmaz; su ve köpük elektronik donanımı bozar.'),
  ('Bir binada acil çıkış kapıları neden çıkış yönünde açılacak biçimde tasarlanır?', 'Panikte kalabalık itişinde kapının içe doğru kapanıp tıkanmasını önlemek için', ['Kapının daha ucuz olması ve montajının kolay olması için', 'Hırsızlığı kolaylaştırmak için', 'Rüzgâr alması için'], 'Kalabalık kapıya doğru yığıldığında içe açılan kapı açılamaz hâle gelir; dışa açılan kapı tahliyeyi hızlandırır.'),
  ('Türkiye\'de işyeri gürültü yönetmeliğinde 8 saatlik günlük maruziyet için \'üst maruziyet eylem değeri\' kaç dB(A)\'dır?', '85', ['80', '95', '75'], 'Alt eylem değeri 80, üst eylem değeri 85 dB(A)\'dır; bu düzeylerde işverenin işitme koruyucu sağlaması ve sağlık gözetimi gibi yükümlülükleri başlar.'),
  ('Düşme durdurma sisteminde şok emicinin işlevi nedir?', 'Düşme anında kemeri ve vücuda gelen kuvveti sınırlamak', ['Halatı gererek çalışanın düşmesini hızlandırmak', 'Çalışanı yukarı çekmek', 'Kemeri sıkılaştırmak'], 'Düşen kişinin durmasında oluşan darbe kuvveti şok emici ile azaltılır; aksi hâlde kuvvet iç organlara ve bağlantı noktasına zarar verir.'),
  ('Asitleri seyreltirken \'önce su, sonra asit\' kuralı neden uygulanır?', 'Asit sudan çok ısı çıkarıp sıçrayabileceği için asit yavaşça suya eklenir', ['Asit suyla hiç tepkimeye girmediği için hangisi önce konulsa fark etmez', 'Su daha ucuz olduğu için önce konur', 'Kabın daha çok dolması için'], 'Derişik asidin suya karışması ekzotermiktir. Suya yavaşça asit eklemek ısıyı dağıtır ve sıçrama riskini azaltır.'),
  ('Bir tasarım ekibi tek kişinin karar verdiği, hiç bağımsız inceleme yapılmayan bir hat kurmuştur. Bu yapının en önemli zaafı hangisidir?', 'Tek hata noktası; tasarımcının gözden kaçırdığı hata fark edilmez', ['Maliyetin kesinlikle düşmesi', 'Sürenin uzaması', 'Belgelerin çok olması ve toplantıların uzaması'], 'Bağımsız inceleme, ortak bir yanılgıyı yakalayan ikinci savunma katmanıdır. Olmadığında tek kişinin varsayım hatası ürüne taşınır.'),
  ('Hızlı-yavaş yaşlanan ekipmanlarda tek tip sabit aralıklı bakımın en önemli sakıncası nedir?', 'Bazı parçaların erken değiştirilip bazılarının arızadan sonra yakalanması', ['Bakımın hiç yapılmaması', 'Parça maliyetinin sıfır olması', 'Bakım personelinin fazla olması ve yedek parça stokunun şişmesi'], 'Aynı aralık, gerçekte farklı hızda bozulan parçalara uyum sağlamaz; kimi parça boşuna değişir, kimi parça aralıktan önce arızalanır.'),
  ('Olay sonrası alınan \'çalışanlara hatırlatma e-postası\' önlemi neden zayıf kabul edilir?', 'Hiyerarşide en zayıf idari kontroldür ve sistemi değiştirmez', ['Çok pahalıdır ve uygulaması aylarca zaman alır', 'Çok uzun sürer', 'Yasa tarafından yasaklanmıştır'], 'E-posta davranışa bağımlıdır ve zamanla unutulur; mühendislik kontrolleri gibi sistem düzeyinde önlemler daha kalıcıdır.'),
  ('Bir hata ağacında üst olay, iki bağımsız alt olaydan en az biri gerçekleşince oluşuyor (VEYA kapısı). Alt olay olasılıkları 0,1 ve 0,2 ise üst olay olasılığı kaçtır?', '0,28', ['0,30', '0,02', '0,20'], 'VEYA kapısı için P = 1 − (1 − 0,1)(1 − 0,2) = 1 − 0,72 = 0,28\'dir.'),
  ('BAC = 300, EV = 120, AC = 150 (bin TL). Kalan işin bütçeye uyacak şekilde yapılması için gerekli TCPI = (BAC − EV)/(BAC − AC) kaçtır?', '1,2', ['0,8', '1,5', '0,67'], 'TCPI = (300 − 120)/(300 − 150) = 180/150 = 1,2\'dir. 1\'in üzeri kalan işte daha verimli olmak gerektiğini gösterir.'),
  ('Bir ağda A (4 gün) sonrası B (5 gün) ve C (3 gün) paralel başlar; D (6 gün) yalnız B bitince, E (2 gün) yalnız C bitince başlar; proje F (1 gün) ile, D ve E bitince biter. Kritik yolun süresi kaç gündür?', '16 gün', ['12 gün', '14 gün', 'Her yol toplanıp 21 gün bulunur, çünkü tüm etkinlikler art arda yapılır'], 'En uzun yol A-B-D-F = 4 + 5 + 6 + 1 = 16 gündür. A-C-E-F yolu 10 gündür.'),
  ('Bir etkinliğin ardıl etkinliklerinin en geç başlama zamanları 9. ve 12. gündür. Etkinlik 3 gün sürüyorsa en geç bitişi (LF) kaçıncı gündür?', '9. gün', ['12. gün', '6. gün', '15. gün'], 'Geri geçişte LF, ardılların en geç başlamalarının en küçüğüdür: min(9, 12) = 9. gün. Etkinliğin en geç başlaması 9 − 3 = 6. gündür.'),
  ('Proje yöneticisi bütün çabasını bolluğu 10 gün olan etkinliğe harcıyor, kritik yoldakilere ise bakmıyor. Bu yaklaşım için doğru değerlendirme hangisidir?', 'Verimsizdir; proje süresini kritik yol belirler', ['Doğrudur; bolluk olan iş en önemlidir', 'Doğrudur; kritik yol önemsizdir', 'Zararsızdır; hiçbir etki yaratmaz ve yönetim hiç incelenmez'], 'Dikkat ve kaynak önce kritik yola yönlendirilmelidir; bolluk içindeki işler gecikse de proje bitişi hemen etkilenmez.'),
  ('Bir etkinliğin süresi artınca ağdaki başka etkinliğin bolluğunun azalması neyi gösterir?', 'Aynı yolu paylaşan etkinliklerin bolluğu ortak kullanılır', ['Bolluk her etkinliğe bağımsız ayrılmıştır', 'Bolluk hiçbir zaman değişmez', 'Kritik yol her zaman tek etkinlikten oluşur ve ortak bolluk kavramı geçerli değildir'], 'Bir yol üzerindeki etkinlikler aynı bolluğu paylaşır; biri kullanınca diğerlerinin payı küçülür.'),
  ('PERT\'in etkinlik süresini beta dağılımıyla yaklaştırması hangi özelliği taşır?', 'Süreler üst sınırlıdır ve çarpık dağılabilir', ['Süreler tam simetrik normal dağılır', 'Süreler her zaman eşit olasılıklıdır', 'Süreler yalnızca tam sayı değerlerini alabilir ve uç değerler hiç görülmez'], 'Beta dağılımı iyimser ve kötümser sınırlar arasında, çarpık olabilen süreleri modeller; ortalama (a+4m+b)/6 bu yaklaşımın sonucudur.'),
  ('PERT\'in yaygın eleştirilerinden biri, birden çok yolun kritiğe yakın olduğunda ne olduğuna ilişkindir. Bu eleştiri nedir?', 'Proje süresi kritik yol süresi tahmininden daha uzun çıkma eğilimindedir', ['Proje süresi hep daha kısa çıkar', 'Varyans hiç hesaplanamaz', 'PERT\'in tüm yolların hesaba katılmasını hiçbir koşulda gerektirmemesi ve yalnızca bir yolu kullanması'], 'Birleşen yollarda en uzun yolun beklenen değeri gerçek beklenen süreyi küçümser; bu \'birleşme yanlılığı\' olarak bilinir.'),
  ('Bir ev yapımı WBS\'sinde \'Temel\' başlığı altında kazı, kalıp, demir, beton alt kalemleri varsa \'Temel\' hangi düzeydedir?', 'Üst düzey paket', ['En alt düzey iş paketi', 'Kilometre taşı', 'Tek başına süresi hesaplanan en küçük görev ve kaynak atanan bir birim'], 'Alt kalemleri olan öğe üst düzeydedir; yalnız en alta inen kalemlerin tahmini yapılır.'),
  ('Proje süresi sabit tutulup kapsam büyütülürse üçlü kısıt dengesinin korunması için hangisi gerekir?', 'Kaynak, maliyet ya da kalite tarafında bir ödünleşme', ['Hiçbir değişiklik gerekmez', 'Yalnızca takvim kısalır', 'Bütçe otomatik olarak aynı kalır ve ek kaynak çıkarılması gerekmez'], 'Kısıtlar birbirine bağlıdır. Süre sabitken kapsam artarsa ek kaynak ya da kalite taviziyle denge kurulur.'),
  ('Monte Carlo benzetiminin proje takviminde sağladığı en önemli katkı nedir?', 'Belirsiz sürelerle birçok senaryo üretip bitiş tarihi için olasılık dağılımı vermesi', ['Tek bir kesin bitiş tarihi bulması', 'Kaynak sayısını sabitlemesi', 'Risklerin tümünü ortadan kaldırması ve belirsizliği hesaba katmadan çalışması'], 'Monte Carlo, süre ve maliyet tahminlerinden binlerce rastgele senaryo üretir; sonuç olarak \'şu tarihe kadar bitme olasılığı yüzde kaç\' bilgisi verir.'),
  ('Takım sprint boyunca sürekli yeni iş eklenmesine izin veriyor ve sprint hedefi hiç tutmuyor. Scrum açısından asıl sorun nedir?', 'Sprint kapsamının korunmaması ve hedefin bulanıklaşması', ['Sprintin çok kısa olması', 'Daily Scrum\'ın çok sık yapılması', 'Takım üyelerinin çok sayıda uzman olması ve işin kolay paylaşılması'], 'Sprint hedefi odak sağlar; sprint içinde kapsam kontrolsüz genişlerse planlama anlamını yitirir. Değişiklikler ürün sahibiyle görüşülerek ele alınır.'),
  ('Little Yasası (Little\'s Law) iş akışı için hangi ilişkiyi verir?', 'Ortalama çevrim süresi = devam eden iş sayısı / teslim hızı', ['Teslim hızı = devam eden iş × çevrim süresi', 'Çevrim süresi = teslim hızı − iş sayısı', 'Çevrim süresi iş sayısından bağımsızdır ve yalnızca insan sayısına bağlıdır'], 'Kararlı bir sistemde WIP = çıkış hızı × çevrim süresidir. WIP azaltıldığında çevrim süresi kısalır.'),
  ('Bir ekipte ortalama devam eden iş (WIP) 12, haftada ortalama 4 iş teslim ediliyor. Little Yasası\'na göre ortalama çevrim süresi kaç haftadır?', '3', ['48', '8', '0,33 hafta'], 'Çevrim süresi = WIP/teslim hızı = 12/4 = 3 haftadır.'),
  ('Gereksinimleri belirsiz, müşterinin ne istediğini görerek keşfettiği bir mobil uygulama için hangi yaklaşım daha uygundur?', 'Kısa döngülü, geri bildirime açık çevik yaklaşım', ['Gereksinimlerin baştan dondurulduğu şelale', 'Hiç planlamadan doğrudan teslim', 'Yalnızca en baştan yazılan ve imzalanan tek kapsamlı sözleşme'], 'Belirsiz ve değişken gereksinimlerde kısa iterasyonlar erken geri bildirimle yanlış yönde yatırımı sınırlar.'),
  ('Kritik zincir yönteminde \'çoklu görev\' neden zararlı görülür?', 'Geçiş maliyeti nedeniyle her işin süresi uzar', ['İşler hızla biter', 'Maliyet sıfırlanır', 'İşler arası geçişin kaliteyi kesinlikle artırması ve motivasyonu yükseltmesi'], 'Bir kişi birkaç işi aynı anda yürütürse her biri geç biter ve geçişlerde zaman kaybı olur; önce biri bitirilmelidir.'),
  ('Hiçbir nokta kontrol sınırı dışına çıkmamış ama ardışık 9 nokta merkez çizginin aynı tarafında yer alıyorsa ne söylenebilir?', 'Süreç ortalamasında bir kayma olabileceği için araştırılmalıdır', ['Süreç tamamen kararlıdır', 'Grafik hatalıdır ve atılmalıdır', 'Süreç kesinlikle şartnameye uygundur ve hiçbir müdahale gerekmez ve örnekleme sıklığı da azaltılabilir'], 'Aynı yöndeki uzun seri rastgele olamayacak kadar olasılığı düşük bir örüntüdür; sınırlar içinde olsa bile özel neden aranır.'),
  ('Tüketici riski (β) ile üretici riski (α) arasındaki fark nedir?', 'Tüketici riski kötü partinin kabul edilmesi, üretici riski iyi partinin reddedilmesidir', ['İkisi aynı risktir', 'Tüketici riski iyi partinin reddi, üretici riski kötü partinin kabulüdür', 'İkisi de yalnızca nakliye gecikmesinden doğan ek maliyetlerdir'], 'Üretici riski (α) iyi bir partinin yanlışlıkla reddi; tüketici riski (β) kötü bir partinin yanlışlıkla kabulüdür.'),
  ('Bir işletmede kaza sıklığı iki yıldır sıfır ve bu durum \'güvenlik mükemmel\' olarak yorumlanıyor. Bu yorumun zayıflığı nedir?', 'Kazanın olmaması riskin olmadığını göstermez; ramak kala ve öncü göstergeler de izlenmelidir', ['Sıfır kaza her zaman mükemmel güvenliği kanıtlar', 'Kaza sayısı hiç anlamlı bir gösterge değildir', 'Sıfır kaza gerçekçi değildir ve verinin tümü mutlaka sahte olmalıdır'], 'Şans ve düşük maruziyet de kazasızlığı açıklayabilir; uygulama kalitesi ancak öncü göstergelerle görülür.'),
  ('ISO 13849-1\'de emniyet fonksiyonlarının güvenilirliği hangi harfle sınıflandırılan düzeylerle ifade edilir?', 'Performans düzeyi', ['Emniyet bütünlüğü düzeyi 1-4 yalnızca', 'Kalite sınıfı I-V', 'Tehlike sınıfı A-F olarak harflendirilen gösterge'], 'ISO 13849-1 performans düzeyi (PL) kullanır; PL e en yüksek düzeydir. IEC 62061/61508 ise SIL kullanır.'),
  ('Bir yük 1000 kg ağırlığında ve iki eşit sapanla, sapanlar dikeyle 60° açı yaparak kaldırılıyor. Her sapandaki kuvvet W/(2·cos60°) formülüyle yaklaşık kaç kgf\'tir?', '1000', ['500', '2000', '577, çünkü sapan açısı küçüldükçe kuvvet de aynı oranda azalır'], 'cos60° = 0,5; her sapanda 1000/(2 × 0,5) = 1000 kgf oluşur. Açı büyüdükçe sapan yükü artar.'),
  ('ATEX bölge sınıflandırmasında gaz için \'Zon 0\' nerede uygulanır?', 'Patlayıcı gaz ortamının sürekli ya da uzun süre bulunduğu yerlerde', ['Hiç gaz bulunmayan yerlerde', 'Yalnızca ofislerde', 'Gaz ortamının çok nadiren ve çok kısa süreyle oluştuğu yerlerde'], 'Zon 0 sürekli ya da uzun süreli, Zon 1 normal çalışmada ara sıra, Zon 2 nadir ve kısa süreli patlayıcı gaz bulunmasıdır.'),
  ('Bir cihazın arıza oranı 0,0004 arıza/saat ve sabittir. Ortalama arızalar arası süre kaç saattir?', '2500', ['250', '4000', '0,0004, çünkü arıza oranı doğrudan ortalama süreye eşittir'], 'Sabit arıza oranında MTBF = 1/λ = 1/0,0004 = 2500 saattir.'),
  ('Hızlandırılmış ömür testlerinin amacı nedir?', 'Yüksek stresle arızayı hızlandırıp normal koşullardaki ömrü kısa sürede tahmin etmek', ['Ürünü olabildiğince çabuk kırmak', 'Maliyeti yükseltmek', 'Normal koşulda arıza veren tüm bileşenleri gizleyip testi başarılı göstermek'], 'Sıcaklık, titreşim ya da gerilim artırılarak kısa sürede arıza verisi toplanır; model aracılığıyla gerçek koşul ömrü kestirilir.'),
  ('Bir tasarım FMEA\'sında A hatası Ş = 9, O = 2, T = 3; B hatası Ş = 4, O = 5, T = 4 puan alıyor. RPN\'ye göre öncelik hangisidir ve neden bunun tek ölçüt olmaması gerekir?', 'B (RPN 80) ama yüksek şiddetli A (RPN 54) ayrıca ele alınmalı', ['A, çünkü RPN yüksektir', 'İkisi eşittir', 'A (RPN 54) ve B (RPN 80) toplamı 134 olduğundan öncelik aynı sırada yürütülür'], 'RPN: A = 54, B = 80. Düşük RPN\'ye rağmen şiddeti 9 olan hata güvenlik açısından önceliklendirilmeli; yeni yöntemler \'eylem önceliği\' (AP) kullanır.'),
  ('Gürbüz tasarım (robust design) yaklaşımının temel fikri nedir?', 'Değişkenliği doğuran gürültü etkenlerini yok etmek yerine ürünü bunlara duyarsız kılmak', ['Her gürültü kaynağını ortadan kaldırmak', 'Toleransları olabildiğince sıkılaştırmak', 'Ürünün tüm bileşenlerinin pahalı özel malzemeden yapılması'], 'Gürbüz tasarım, kontrol faktörlerinin ayarıyla ürün performansının çevre ve üretim değişimlerinden az etkilenmesini sağlar.'),
  ('Kesirli faktöriyel tasarımın tam faktöriyele göre bedeli nedir?', 'Bazı etkileşimler diğer etkilerle karışır', ['Daha fazla deney gerektirir', 'Hiç sonuç vermez', 'Faktör sayısının hiç değişmemesi ve tüm etkilerin birbirinden bağımsız ölçülmesi'], 'Kesirli tasarım deney sayısını azaltır; karşılığında yüksek dereceli etkileşimler başka etkilerle ayrılamaz hâle gelir.'),
  ('Bir mühendis, güvenlik sistemini devre dışı bırakmanın üretimi %5 artıracağını görüyor ve amiri bunu istiyor. Meslek etiği açısından en doğru davranış hangisidir?', 'Güvenlik riskini yazılı olarak bildirip sistemi devre dışı bırakmayı reddetmek', ['Sessizce kabul etmek', 'Sistemi sökmek', 'Riski kayda geçirmeden amirin sorumluluk aldığını söylemesiyle yetinmek'], 'Mühendislik etiği kamu güvenliğini önce tutar; riskler belgelenip ilgili kanallara iletilir, güvenlik önlemi kaldırılmaz.'),
  ('Yanlış varsayımlarla yazılmış bir gereksinim şartnamesi, tasarım aşamalarında fark edilmezse en pahalı sonuç ne zaman ortaya çıkar?', 'Üretim sonrası veya sahada kullanımda', ['Planlama aşamasında', 'Toplantı sırasında, tasarım ekibi bir araya geldiğinde', 'İlk taslak aşamasında çizim sırasında'], 'Hata ne kadar geç bulunursa düzeltme maliyeti o kadar yüksektir; sahada bulunan gereksinim hatası tasarım, üretim ve geri çağırma maliyetini birlikte doğurur.'),
  ('Üç istasyonlu hatta istasyon süreleri 40, 55 ve 45 saniyedir. Hattın darboğaz süresi ve hat dengesi verimi (toplam süre / (istasyon × darboğaz)) yaklaşık nedir?', '55 s; yaklaşık %85', ['40 s; yaklaşık %100', '45 s; yaklaşık %50', '55 s; yaklaşık %50, çünkü toplam süre ortalamaya bölünerek bulunur'], 'Toplam 140 s; verim = 140/(3 × 55) = 140/165 ≈ 0,85\'tir. Darboğaz en yavaş istasyondur.'),
  ('Bir fabrika stokları azaltırken arıza ve kalite sorunlarının da arttığını fark ediyor. Yalın düşünceye göre bu durum neyi gösterir?', 'Stokun daha önce sorunları gizlediğini; kök nedenlerin çözülmesi gerektiğini', ['Stok azaltmanın yanlış olduğunu', 'Sorunların tesadüf olduğunu', 'Stoğu geri artırıp sorunları yeniden gizlemenin kalıcı çözüm olduğunu'], 'Yalın bakışta stok, sorunları örten bir tampondur; azaltıldığında sorunlar görünür olur ve çözülmeleri gerekir.'),
  ('İki risk var: A olasılığı %30, etkisi 40 bin TL; B olasılığı %10, etkisi 100 bin TL. EMV değerlerine göre hangi risk öncelikli olur?', 'A (12 bin TL), B\'nin 10 bin TL değerinden büyük', ['B (10 bin TL), A\'dan büyük', 'İkisi eşit', 'A ve B\'nin EMV değerleri toplanarak ortalamaları alınır ve ikisi de aynı sıraya girer'], 'A: 0,30 × 40 = 12 bin TL; B: 0,10 × 100 = 10 bin TL. A\'nın beklenen kaybı büyüktür.'),
  ('Karar ağacında A seçeneği: %60 olasılıkla 100 bin TL kazanç, %40 olasılıkla 50 bin TL zarar. A\'nın beklenen parasal değeri kaç bin TL\'dir?', '40', ['60', '20', '110'], 'EMV = 0,6 × 100 + 0,4 × (−50) = 60 − 20 = 40 bin TL\'dir.'),
  ('Bir köprü projesinde çevre grupları sürece hiç dahil edilmemiştir. İnşaat başlarken dava açıyorlar. Proje yönetimi açısından asıl hata nedir?', 'Önemli paydaşın erken belirlenip katılımının sağlanmaması', ['Köprünün çok uzun olması ve inşaat süresinin kısa olması', 'Takvimin çok kısa olması', 'Bütçenin sabit tutulması'], 'Paydaş analizi başlangıçta yapılmalı; etkilenen ve ilgili gruplar önceden dinlenmezse risk sonradan itiraz ve gecikme olarak döner.'),
  ('Altı Sigma \'sigma düzeyi\' hesabında uzun vadeli kayma (1,5σ) varsayımı neden kullanılır?', 'Süreç ortalamasının zamanla kayabileceği gözlemine dayanır', ['Süreç ortalaması hiç kaymaz', 'Hesabı kolaylaştırmak için tamamen rastgele seçilmiştir', 'Her müşterinin her ürünü tam 1,5 kat daha sıkı kullanacağı varsayımı nedeniyle'], 'Motorola gözlemlerine göre süreçler uzun vadede ortalamadan ±1,5σ sapar; bu yüzden 6σ kısa vadede 3,4 DPMO\'ya karşılık gelir.'),
  ('Bir projede kalite artırılması isteniyorsa üçlü kısıtın diğer bileşenleri nasıl etkilenebilir?', 'Ek test ve düzeltme nedeniyle süre ve maliyet artabilir', ['Hiçbir şey değişmez', 'Süre ve maliyet azalır', 'Maliyet düşer ama süre aynı kalır, çünkü kalite ile maliyet arasında ilişki bulunmaz'], 'Daha yüksek kalite genellikle daha fazla inceleme, tasarım ve test emeği gerektirir; bu da süre ve maliyeti yükseltebilir.'),
  ('BAC = 1000 ve proje ilerlemesi %25, AC = 300 ise CPI kaçtır?', '0,83', ['1,20', '0,25', '0,30'], 'EV = 0,25 × 1000 = 250; CPI = EV/AC = 250/300 ≈ 0,83\'tür.'),
  ('BAC = 1000, EV = 400, AC = 500 ise sapma tipik olarak devam etmeyecek varsayımıyla tamamlama tahmini (EAC = AC + BAC − EV) kaçtır?', '1100', ['1250', '1000', '900'], 'Sapma tek seferlik kabul edilirse EAC = 500 + (1000 − 400) = 1100\'dür.'),
  ('EAC = 1250, AC = 500 ise tamamlanmak için kalan tahmini maliyet (ETC) kaçtır?', '750', ['1750', '500', '1250'], 'ETC = EAC − AC = 1250 − 500 = 750\'dir.'),
  ('Bir projede alınan dersler hiç yazılmıyor ve ekip dağılıyor. Sonraki projelerde ne olması beklenir?', 'Aynı hataların tekrarlanması ve kurumsal öğrenmenin kaybı', ['Hataların kendiliğinden azalması', 'Maliyetin düşmesi', 'Ekip üyelerinin tamamının aynı bilgiyi koruyup ihtiyaç duyulduğunda ortaklaşa hatırlaması'], 'Bilgi yazılı olarak aktarılmazsa kişilere bağlı kalır; kişiler ayrılınca aynı hatalar yeni ekiplerce yeniden yapılır.'),
  ('Bir gazın \'tavan değeri\' (ceiling) maruziyet sınırı için doğru ifade hangisidir?', 'Çalışma süresinin herhangi bir anında aşılmaması gereken derişimdir', ['Sekiz saatlik ortalamadır', 'Yalnızca bir yıllık ortalamadır', 'Vardiya boyunca bir kez aşılması serbest olan üst sınırdır'], 'Tavan sınır değeri anlık da aşılamaz; çok zehirli ya da tahriş edici gazlar için kısa maruziyetin bile zararlı olduğu durumlarda konur.'),
  ('Hidrojen sülfür (H₂S) için neden \'koku alma duyusuna güvenilmez\' denir?', 'Yüksek derişimde koku alma siniri uyuşup koku hissedilmez olur', ['Gazın hiç kokusu olmaz', 'Düşük derişimde zehirli olmaz', 'Koku yalnızca düşük sıcaklıkta oluşur ve ısındıkça yok olur'], 'H₂S düşük derişimde çürük yumurta kokar; yüksek derişimde koku alma duyusu felç olur ve kişi tehlikeyi fark etmeden bayılabilir.'),
  ('İşyerinde bir kimyasal ambalajı başka kaba boşaltılırken etiketsiz bırakılırsa ne risk doğar?', 'Madde kimliği ve tehlikesi bilinmediğinden yanlış kullanım ve zehirlenme olabilir', ['Madde değeri artar', 'Kapta çatlak oluşur', 'Maddenin raf ömrü kısalarak uzun süre depolanamaz hâle gelir'], 'Etiket, tehlike iletişiminin temelidir. Etiketsiz kap yanlış maddeyle karışıma veya yanlış ilk yardıma neden olur.'),
  ('Üç özdeş makinenin her biri 80 dB üretiyor. Toplam ses düzeyi yaklaşık kaç dB\'dir?', '85', ['83', '240', '90'], '10·log₁₀(3) ≈ 4,8 dB eklenir; 80 + 4,8 ≈ 85 dB\'dir.'),
  ('Bir toz patlamasının oluşması için klasik \'patlama beşgeni\' hangi koşulları içerir?', 'Yakıt (toz), oksijen, tutuşturucu kaynak, dağılma (süspansiyon) ve sınırlama', ['Yalnızca yakıt ve ısı', 'Yalnızca oksijen ve gaz', 'Yakıt, su, soğuk ve basınç koşulunun bir arada bulunması'], 'Yangın üçgenine ek olarak tozun havada süspanse olması ve kapalı hacimde sınırlanması patlamayı mümkün kılar; un ve talaş tozları örnektir.'),
  ('Bir fabrikada yönetim sadece \'işçi dikkatsizliğine\' odaklanıp kazaların nedenini tasarım ve düzene bağlamıyor. Bu yaklaşımı hangi görüş eleştirir?', 'Sistem yaklaşımı; hata yapan kişiye değil sistemdeki zayıflıklara bakar', ['Domino modeli yalnızca', 'Buzdağı modeli yalnızca', 'Heinrich\'in yaklaşımı tek başına yeterli olup sistemle ilgili bir eleştiri içermez'], 'Sistem yaklaşımı (Reason) insanları hataya iten koşullara odaklanır; savunma katmanlarını güçlendirmeyi amaçlar.'),
  ('20 alt gruptan alınan X-bar ortalamalarının genel ortalaması 12,0 ve R-ortalaması 1,0\'dır. n = 5 için A2 = 0,577 ise X-bar grafiğinin UCL değeri yaklaşık kaçtır?', '12,58', ['12,00', '13,58', '11,42'], 'UCL = X̿ + A2·R̄ = 12,0 + 0,577 × 1,0 = 12,58\'dir.'),
  ('Ölçüm sistemi analizinde \'bias\' ile \'lineerlik\' arasındaki fark nedir?', 'Bias sabit sapmadır, lineerlik ise sapmanın ölçüm aralığı boyunca değişmesidir', ['İkisi aynıdır', 'Bias tekrarlanabilirliktir', 'Lineerlik yalnızca bir noktadaki sapmadır ve aralık boyunca hiç değişmez'], 'Bias gerçek değerle ortalama arasındaki farktır; lineerlik bu farkın ölçüm aralığında tutarlı olup olmadığını gösterir.'),
  ('Başlatıcı olay sıklığı yılda 0,1 ve iki bağımsız koruma katmanının başarısızlık olasılıkları 0,1 ve 0,01 ise sonuç sıklığı yılda kaçtır?', '0,0001', ['0,001', '0,01', '0,11, çünkü başlatıcı sıklığı ve katmanların başarısızlık olasılıkları toplanır'], 'LOPA\'da sıklıklar ve olasılıklar çarpılır: 0,1 × 0,1 × 0,01 = 10⁻⁴ olay/yıl.'),
  ('IEC 61508\'de düşük talep modunda SIL 2 için PFDavg aralığı hangisidir?', '10⁻³ ile 10⁻² arası', ['10⁻² ile 10⁻¹ arasındaki düşük talep aralığı', '10⁻⁴ ile 10⁻³ arası', '10⁻⁶ ile 10⁻⁵ arası'], 'SIL 1: 10⁻²–10⁻¹; SIL 2: 10⁻³–10⁻²; SIL 3: 10⁻⁴–10⁻³; SIL 4: 10⁻⁵–10⁻⁴ aralığındadır.'),
  ('Soruşturma raporunda \'önlem: işçilere uyarı yazısı gönderilsin\' dışında bir mühendislik önlemi yoksa bu hangi sorunu gösterir?', 'Önlemler hiyerarşinin en zayıf basamağında kalmıştır', ['Soruşturma çok ayrıntılıdır', 'Maliyet yüksektir', 'Rapor çok kısa olduğu için tüm önlemler yeterli sayılır'], 'Etkin önlemler tehlikeyi gidermeye veya mühendislikle kontrol etmeye yönelir; yalnızca uyarı idari ve zayıf bir önlemdir.'),
  ('Bir tedarikçinin PPM değeri düşük ama teslimat gecikmeleri sık. Tedarikçi değerlendirmesinde ne yapılmalıdır?', 'Kalite, teslimat, maliyet ve hizmet gibi çok ölçütlü puanlama kullanılmalıdır', ['Yalnızca PPM\'e bakılmalıdır', 'Tedarikçi hemen değiştirilmelidir', 'Gecikmeleri önemsemeyip yalnızca kalite verisine dayalı kararla ödeme planını belirlemek'], 'Tek göstergeye bakmak yanıltır; dengeli puan kartı, tedarikçinin güçlü ve zayıf yönlerini bütün olarak gösterir.'),
  ('A (2 gün) ve B (3 gün) başlangıçtan paralel başlar. C (4 gün) A\'dan, D (2 gün) hem A hem B\'den sonra başlar. E (3 gün) C ve D bitince başlar ve projeyi bitirir. Proje süresi kaç gündür?', '9 gün', ['8 gün', '10 gün', '14 gün'], 'C, A bitince (2. gün) başlar ve 6\'da biter. D, B bitince (3. gün) başlar ve 5\'te biter. E, 6\'da başlar ve 9\'da biter; süre 9 gündür.'),
  ('Önceki ağda (A 2, B 3, C 4, D 2, E 3 gün) D etkinliğinin toplam bolluğu kaç gündür?', '1 gün', ['0 gün', '2 gün', '3 gün'], 'D en erken 3. günde başlar. E en geç 6. günde başlamak zorunda olduğundan D en geç 6 − 2 = 4. günde başlayabilir. Bolluk = 4 − 3 = 1 gündür.'),
  ('Maliyet eğimleri A: 500 TL/gün, B: 300 TL/gün olan iki kritik paralel yol varsa (her yol tek etkinlik) projeyi 1 gün kısaltmak için neden sadece B\'yi kısaltmak yetmez?', 'İki yol da kritik olduğundan ikisinin birden kısaltılması gerekir', ['B daha ucuzdur', 'A daha ucuzdur', 'Yalnızca bir yol kritik sayılır ve diğeri bolluklu olduğundan hiç değişmez'], 'Paralel iki kritik yoldan yalnızca biri kısalırsa proje süresi diğer yoldan belirlenir; bu durumda iki yol birlikte kısaltılır (500 + 300 = 800 TL/gün).'),
  ('Bir risk için olasılık 0,5 ve etki 40 bin TL\'dir. Bu riske karşı 12 bin TL\'ye azaltma önlemi alınırsa olasılık 0,1\'e düşüyor. Önlem ekonomik midir?', 'Evet; beklenen kayıp 20\'den 4\'e düşer, kazanç 16 bin TL, maliyet 12 bin TL', ['Hayır; önlem maliyeti kazançtan fazladır', 'Hayır; olasılık hâlâ sıfır değildir', 'Evet; çünkü maliyetin 12 bin TL olması riskin tam sıfırlandığını gösterir'], 'EMV 0,5 × 40 = 20 bin TL iken 0,1 × 40 = 4 bin TL\'ye iner; 16 bin TL azalmaya karşı 12 bin TL harcama net kazanç sağlar.'),
  ('Bir şirket her riski kabul etmek yerine yalnızca düşük riskleri kabul edip yüksek riskler için önlem alıyor. Bu yaklaşım nasıl değerlendirilir?', 'Uygundur; kaynakları yüksek öncelikli risklere yönlendirir', ['Yanlıştır, tüm riskler sıfırlanmalıdır', 'Yanlıştır, hiçbir önlem gerekmez', 'Yalnızca küçük riskleri azaltıp büyük riskleri değerlendirme dışı tutmak daha doğrudur'], 'Önceliklendirme, sınırlı kaynakların en çok risk azaltan yere gitmesini sağlar; tüm riskleri sıfırlamak gerçekçi değildir.'),
  ('Cihaz A satın alma 10 000 TL ve yıllık işletme 2 000 TL; cihaz B satın alma 14 000 TL ve yıllık işletme 1 000 TL. İskontosuz 6 yıllık toplam maliyet hangisinde düşüktür?', 'B (20 000 TL), A\'dan (22 000 TL) düşüktür', ['A (22 000 TL), B\'den (20 000 TL) düşüktür', 'İkisi eşittir', 'B 14 000 TL ile A 12 000 TL\'den daha yüksek olur'], 'A: 10 000 + 6 × 2 000 = 22 000; B: 14 000 + 6 × 1 000 = 20 000 TL. B daha ekonomiktir.'),
];
